#!/bin/sh
# Prints the Homebrew formula `crystal-ext` for <version>, with the URLs of the
# release archives on GitHub and the SHA256 sums of the local copies in <dir>.
#
# Usage: formula.sh <version> <dir> [<repository>]
set -eu

version=$1
dir=$2
repository=${3:-${GITHUB_REPOSITORY:-jochenseeber/crystal}}

# `+` is literal in a URL path, but encode it so no tool reads it as a space.
download="https://github.com/$repository/releases/download/$(echo "$version" | sed 's/+/%2B/g')"

sha256() {
  file="$dir/crystal-$1.tar.gz"
  if [ ! -f "$file" ]; then
    echo "Missing $file" >&2
    exit 1
  fi
  if command -v sha256sum >/dev/null; then
    sha256sum "$file" | cut -d' ' -f1
  else
    shasum -a 256 "$file" | cut -d' ' -f1
  fi
}

darwin_arm64=$(sha256 darwin-arm64-system-static)
linux_arm64=$(sha256 linux-arm64-musl-static)
linux_amd64=$(sha256 linux-amd64-musl-static)

cat <<EOF
# Generated by .github/ext-release/formula.sh in $repository.
class CrystalExt < Formula
  desc "Crystal compiler with not yet merged upstream pull requests"
  homepage "https://github.com/$repository"
  version "$version"
  license "Apache-2.0"

  on_macos do
    depends_on arch: :arm64

    url "$download/crystal-darwin-arm64-system-static.tar.gz"
    sha256 "$darwin_arm64"
  end

  on_linux do
    on_arm do
      url "$download/crystal-linux-arm64-musl-static.tar.gz"
      sha256 "$linux_arm64"
    end
    on_intel do
      url "$download/crystal-linux-amd64-musl-static.tar.gz"
      sha256 "$linux_amd64"
    end
  end

  # The compiler and shards are self-contained; compiled programs link these.
  depends_on "bdw-gc"
  depends_on "gmp"
  depends_on "libyaml"
  depends_on "openssl@3"
  depends_on "pcre2"
  depends_on "pkgconf"

  conflicts_with "crystal", because: "both install \`crystal\` and \`shards\`"

  def install
    libexec.install Dir["*"]

    # Let compiled programs find the libraries Homebrew installs.
    (bin/"crystal").write_env_script libexec/"bin/crystal",
      CRYSTAL_LIBRARY_PATH: "\\\${CRYSTAL_LIBRARY_PATH:-#{HOMEBREW_PREFIX}/lib}"
    bin.install_symlink libexec/"bin/shards"

    bash_completion.install libexec/"share/bash-completion/completions/crystal"
    zsh_completion.install libexec/"share/zsh/site-functions/_crystal"
    fish_completion.install libexec/"share/fish/vendor_completions.d/crystal.fish"
  end

  def caveats
    return unless OS.linux?

    <<~EOS
      The Linux build has no interpreter (\`crystal i\`): it is statically
      linked and can't load C libraries at run time.
    EOS
  end

  test do
    (testpath/"hello.cr").write "puts \\"Hello, Crystal\\"\\n"
    system bin/"crystal", "build", "hello.cr"
    assert_equal "Hello, Crystal\\n", shell_output("./hello")
    assert_match version.to_s, shell_output("#{bin}/crystal --version")
  end
end
EOF
